import java.util.*;

public class Solution {
    static int[][] inserir(int[][] intervalos, int[] novo) {
        List<int[]> out = new ArrayList<>();
        int i = 0, n = intervalos.length;
        while (i < n && intervalos[i][1] < novo[0]) out.add(intervalos[i++]);       // terminam antes
        int ini = novo[0], fim = novo[1];
        while (i < n && intervalos[i][0] <= fim) {                                   // se sobrepõem ou tocam
            ini = Math.min(ini, intervalos[i][0]);
            fim = Math.max(fim, intervalos[i][1]);
            i++;
        }
        out.add(new int[]{ini, fim});
        while (i < n) out.add(intervalos[i++]);                                      // começam depois
        return out.toArray(new int[0][]);
    }
}

