import static org.junit.jupiter.api.Assertions.*;

class SolutionTest {
    @Test void exemplos() {
        assertArrayEquals(new int[][]{{1, 5}, {6, 9}}, Solution.inserir(new int[][]{{1, 3}, {6, 9}}, new int[]{2, 5}));
        assertArrayEquals(new int[][]{{1, 2}, {3, 10}, {12, 16}},
            Solution.inserir(new int[][]{{1, 2}, {3, 5}, {6, 7}, {8, 10}, {12, 16}}, new int[]{4, 8}));
    }

    @Test void pontas() {
        assertArrayEquals(new int[][]{{0, 0}, {2, 3}}, Solution.inserir(new int[][]{{2, 3}}, new int[]{0, 0}));
        assertArrayEquals(new int[][]{{2, 3}, {5, 6}}, Solution.inserir(new int[][]{{2, 3}}, new int[]{5, 6}));
        assertArrayEquals(new int[][]{{4, 4}}, Solution.inserir(new int[][]{}, new int[]{4, 4}));
    }

    @Test void tocarFunde() {
        assertArrayEquals(new int[][]{{1, 5}}, Solution.inserir(new int[][]{{1, 2}, {4, 5}}, new int[]{2, 4}));
    }

    @Test void engoleTudo() {
        assertArrayEquals(new int[][]{{0, 100}}, Solution.inserir(new int[][]{{1, 2}, {5, 6}, {9, 10}}, new int[]{0, 100}));
    }
}

