import java.util.*;

public class Solution {
    // Varredura: inícios e fins ordenados separadamente; um fim <= início libera uma sala antes.
    static int salas(int[][] reunioes) {
        int n = reunioes.length;
        int[] ini = new int[n], fim = new int[n];
        for (int i = 0; i < n; i++) {
            ini[i] = reunioes[i][0];
            fim[i] = reunioes[i][1];
        }
        Arrays.sort(ini);
        Arrays.sort(fim);
        int usadas = 0, maximo = 0, j = 0;
        for (int i = 0; i < n; i++) {
            while (fim[j] <= ini[i]) {
                j++;
                usadas--;
            }
            usadas++;
            maximo = Math.max(maximo, usadas);
        }
        return maximo;
    }
}

