import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

import java.util.*;

class SolutionTest {
    @Test void exemplos() {
        assertEquals(2, Solution.salas(new int[][]{{0, 30}, {5, 10}, {15, 20}}));
        assertEquals(1, Solution.salas(new int[][]{{7, 10}, {2, 4}}));
        assertEquals(0, Solution.salas(new int[][]{}));
    }

    @Test void encostadasUsamUmaSala() {
        assertEquals(1, Solution.salas(new int[][]{{1, 5}, {5, 10}, {10, 12}}));
    }

    @Test void todasJuntas() {
        int[][] r = new int[1000][];
        for (int i = 0; i < r.length; i++) r[i] = new int[]{0, 1 + i};
        assertEquals(1000, Solution.salas(r));
    }

    @Test void aleatorioContraBruta() {
        var rnd = new Random(4);
        for (int t = 0; t < 200; t++) {
            int n = rnd.nextInt(20);
            int[][] r = new int[n][];
            int[] ocup = new int[60];
            for (int i = 0; i < n; i++) {
                int a = rnd.nextInt(50), b = a + 1 + rnd.nextInt(9);
                r[i] = new int[]{a, b};
                for (int x = a; x < b; x++) ocup[x]++;
            }
            assertEquals(Arrays.stream(ocup).max().getAsInt(), Solution.salas(r));
        }
    }
}
